68	// HandlePasteCommits begins a cherry-pick rebase with the commits the user has copied.
69	// Only to be called from the branch commits controller
70	func (self *CherryPickHelper) Paste() error {
71		self.c.Confirm(types.ConfirmOpts{
72			Title: self.c.Tr.CherryPick,
73			Prompt: utils.ResolvePlaceholderString(
74				self.c.Tr.SureCherryPick,
75				map[string]string{
76					"numCommits": strconv.Itoa(len(self.getData().CherryPickedCommits)),
77				}),
78			HandleConfirm: func() error {
79				return self.c.WithWaitingStatusSync(self.c.Tr.CherryPickingStatus, func() error {
80					mustStash := IsWorkingTreeDirtyExceptSubmodules(self.c.Model().Files, self.c.Model().Submodules)
81	
82					self.c.LogAction(self.c.Tr.Actions.CherryPick)
83	
84					if mustStash {
85						if err := self.c.Git().Stash.Push(self.c.Tr.AutoStashForCherryPicking); err != nil {
86							return err
87						}
88					}
89	
90					cherryPickedCommits := self.getData().CherryPickedCommits
91					result := self.c.Git().Rebase.CherryPickCommits(cherryPickedCommits)
92					err := self.rebaseHelper.CheckMergeOrRebaseWithRefreshOptions(result, types.RefreshOptions{Mode: types.SYNC})
93					if err != nil {
94						return result
95					}
96	
97					// Move the selection down by the number of commits we just
98					// cherry-picked, to keep the same commit selected as before.
99					// Don't do this if a rebase todo is selected, because in this
100					// case we are in a rebase and the cherry-picked commits end up
101					// below the selection.
102					if commit := self.c.Contexts().LocalCommits.GetSelected(); commit != nil && !commit.IsTODO() {
103						self.c.Contexts().LocalCommits.MoveSelection(len(cherryPickedCommits))
104						self.c.Contexts().LocalCommits.FocusLine(true)
105					}
106	
107					// If we're in the cherry-picking state at this point, it must
108					// be because there were conflicts. Don't clear the copied
109					// commits in this case, since we might want to abort and try
110					// pasting them again.
111					isInCherryPick, result := self.c.Git().Status.IsInCherryPick()
112					if result != nil {
113						return result
114					}
115					if !isInCherryPick {
116						self.getData().DidPaste = true
117						self.rerender()
118	
119						if mustStash {
120							if err := self.c.Git().Stash.Pop(0); err != nil {
121								return err
122							}
123							self.c.Refresh(types.RefreshOptions{
124								Scope: []types.RefreshableView{types.STASH, types.FILES},
125							})
126						}
127					}
128	
129					return nil
130				})
131			},
132		})
133	
134		return nil
135	}
